// Parse ###LEAD_DATA###...###END_LEAD_DATA### from the AI's reply.
// Supports both fenced (```json ... ```) and unfenced JSON between markers.
// Strips the entire block from the user-visible reply.

const raw = $json.output ?? $json.text ?? $json.response ?? '';

// Match everything between the markers (greedy enough to capture any JSON,
// optional whitespace, optional ```json fences on either side).
const markerRegex = /###LEAD_DATA###([\s\S]*?)###END_LEAD_DATA###/m;
const match = raw.match(markerRegex);

let leadCaptured = false;
let lead = null;
let cleanReply = raw;

if (match) {
  // Strip ```json / ``` fences if the model included them
  const inner = match[1]
    .replace(/^\s*```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();
  try {
    lead = JSON.parse(inner);
    leadCaptured = Boolean(lead.name && lead.service);
    cleanReply = raw.replace(markerRegex, '').trim();
  } catch (err) {
    console.warn('LEAD_DATA JSON parse failed:', err.message, 'Inner:', inner);
  }
}

const trigger = $('WhatsApp Trigger').first().json;
const phone = trigger.messages?.[0]?.from ?? '';
const waName = trigger.contacts?.[0]?.profile?.name ?? '';

return {
  json: { cleanReply, leadCaptured, lead, phone, waName, rawAgentOutput: raw }
};
